CREATE TABLE IF NOT EXISTS users(email TEXT PRIMARY KEY,nickname_key TEXT NOT NULL UNIQUE,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS otp(email TEXT PRIMARY KEY,digest TEXT NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,sent_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,email TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,source_key TEXT UNIQUE,owner_email TEXT NOT NULL DEFAULT '',owner_subject TEXT NOT NULL DEFAULT '',deleted_at TEXT,version INTEGER NOT NULL DEFAULT 1,metadata TEXT NOT NULL,markdown TEXT NOT NULL DEFAULT '',original_drive_id TEXT NOT NULL,markdown_drive_id TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS documents_owner ON documents(owner_email,owner_subject);
CREATE TABLE IF NOT EXISTS sync_jobs(id TEXT PRIMARY KEY,document_id TEXT,kind TEXT NOT NULL,payload TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at INTEGER NOT NULL DEFAULT 0,last_error TEXT);
CREATE TABLE IF NOT EXISTS revisions(id TEXT PRIMARY KEY,document_id TEXT NOT NULL,metadata TEXT NOT NULL,markdown TEXT NOT NULL,drive_id TEXT,created_at TEXT NOT NULL);
